+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ * <p>
+ * The default file name strategy is {@code random}. The other built-in strategy is {@code description}; custom strategies
+ * can be supplied either to the constructor or by fully-qualified class name through {@code default.fileNames}.
+ * <p>
+ * Integrity checking is configured with {@code default.integrity=ignore|repair|fail}. It defaults to {@code ignore}.
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_IGNORE = "ignore";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+
+    /*
+     * The lock is deliberately shared by all store instances in this VM. In particular, initialization must not inspect
+     * a file while another instance is replacing it. The key is canonical, so a folder reached through a link gets the
+     * same lock as the folder reached by its real path.
+     */
+    private static final ConcurrentHashMap<String, StoreState> STORES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean strategyWasSuppliedToConstructor;
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private IntegrityMode integrityMode;
+    private File storeFolder;
+    private File storedRulesFile;
+    private StoreState storeState;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     */
+    public TextFileBasedViolationStore() {
+        this(null, false);
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        this(ruleViolationFileNameStrategy, true);
+    }
+
+    private TextFileBasedViolationStore(RuleViolationFileNameStrategy strategy, boolean suppliedToConstructor) {
+        constructorStrategy = strategy;
+        strategyWasSuppliedToConstructor = suppliedToConstructor;
+        ruleViolationFileNameStrategy = strategy != null ? strategy : TextFileBasedViolationStore::randomFileName;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        boolean creationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        boolean updateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        IntegrityMode configuredIntegrity = integrityMode(properties);
+        RuleViolationFileNameStrategy configuredStrategy = fileNameStrategy(properties);
+        if (configuredIntegrity == IntegrityMode.REPAIR && !updateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s=true", ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        File configuredFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        File configuredStoredRulesFile = new File(configuredFolder, STORED_RULES_FILE_NAME);
+        StoreState state = getStoreState(configuredStoredRulesFile);
+
+        synchronized (state.monitor) {
+            PreparedIndex preparedIndex = prepareIndex(configuredFolder, configuredStoredRulesFile, creationAllowed, configuredIntegrity);
+            FileSyncedProperties index = preparedIndex.index;
+            IntegrityReport report = null;
+            boolean indexChanged = false;
+            if (configuredIntegrity != IntegrityMode.IGNORE) {
+                report = inspect(configuredFolder, configuredStoredRulesFile, index, configuredStrategy);
+                if (configuredIntegrity == IntegrityMode.FAIL) {
+                    if (report.hasProblems()) {
+                        throw new StoreInitializationFailedException(report.message(configuredStoredRulesFile, updateAllowed));
+                    }
+                } else {
+                    indexChanged = repair(configuredFolder, configuredStoredRulesFile, index, report);
+                }
+            }
+
+            if (preparedIndex.absent || indexChanged) {
+                index.syncFileSystem();
+            }
+            state.index = index;
+            storeFolder = configuredFolder;
+            storedRulesFile = configuredStoredRulesFile;
+            storeState = state;
+            storeCreationAllowed = creationAllowed;
+            storeUpdateAllowed = updateAllowed;
+            integrityMode = configuredIntegrity;
+            ruleViolationFileNameStrategy = configuredStrategy;
+        }
+        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), configuredStoredRulesFile.getAbsolutePath());
+    }
