+    private StoreState getStoreState(File file) {
+        try {
+            String canonicalPath = file.getCanonicalPath();
+            return STORES_BY_PATH.computeIfAbsent(canonicalPath, ignored -> new StoreState());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private PreparedIndex prepareIndex(File folder, File indexFile, boolean creationAllowed, IntegrityMode mode) {
+        boolean indexExists = existsAsDirectoryEntry(indexFile.toPath());
+        if (!indexExists && !creationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        ensureFolder(folder);
+        if (indexExists && !isRegularFileWithoutFollowingLinks(indexFile.toPath())) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The violation store index %s must be a regular file directly in its store folder", indexFile.getAbsolutePath()));
+        }
+
+        FileSyncedProperties index = new FileSyncedProperties(indexFile, indexExists);
+        /*
+         * fail is intentionally allowed to work from an in-memory empty index. This lets it compare an absent index with
+         * the folder and, importantly, means a failing initialization never creates that index.
+         */
+        return new PreparedIndex(index, !indexExists);
+    }
+
+    private void ensureFolder(File folder) {
+        Path path = folder.toPath();
+        try {
+            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                if (!folder.mkdirs() && !Files.isDirectory(path)) {
+                    throw new StoreInitializationFailedException(String.format("Cannot create violation store folder %s", folder.getAbsolutePath()));
+                }
+            }
+            if (!Files.isDirectory(path)) {
+                throw new StoreInitializationFailedException(String.format("Violation store path %s is not a directory", folder.getAbsolutePath()));
+            }
+        } catch (SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private IntegrityMode integrityMode(Properties properties) {
+        String value = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE);
+        if (INTEGRITY_IGNORE.equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        if (INTEGRITY_REPAIR.equals(value)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s value '%s'; accepted values are '%s', '%s' and '%s'",
+                INTEGRITY_PROPERTY_NAME, value, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
+    }
+
+    private RuleViolationFileNameStrategy fileNameStrategy(Properties properties) {
+        boolean configured = hasProperty(properties, FILE_NAMES_PROPERTY_NAME);
+        if (strategyWasSuppliedToConstructor) {
+            if (configured) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor", FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+        if (!configured) {
+            return this::randomFileName;
+        }
+
+        String value = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (FILE_NAMES_RANDOM.equals(value)) {
+            return this::randomFileName;
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(value)) {
+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+        return instantiateStrategy(value);
+    }
+
+    private boolean hasProperty(Properties properties, String name) {
+        for (java.util.Enumeration<?> names = properties.propertyNames(); names.hasMoreElements(); ) {
+            if (name.equals(names.nextElement())) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    @MayResolveTypesViaReflection(reason = "This is not part of the import process")
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> type = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(type)) {
+                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            Constructor<?> constructor = type.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s of configured type '%s=%s' (it must implement the strategy and have a public no-argument constructor)",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private static String randomFileName(String ignored) {
+        return UUID.randomUUID().toString();
+    }
+
+    private static String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String keptWord = null;
+        while (matcher.find()) {
+            keptWord = matcher.group(1);
+        }
+        String hash = sha256(description);
+        String prefix = keptWord == null ? "description" : "description-" + keptWord;
+        String result = prefix + "-" + hash;
+        return result.length() <= 200 ? result : result.substring(0, 200);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte b : digest) {
+                result.append(String.format("%02x", b & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronizedStore(() -> storedRules().containsKey(rule.getDescription()));
+        return storedRules().containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        requireInitialized();
+        synchronized (storeState.monitor) {
+            log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+            if (!storeUpdateAllowed) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+            }
+
+            String description = rule.getDescription();
+            String candidateFileName = requireFileName(ruleViolationFileNameStrategy.createRuleFileName(description), description);
+            String existingFileName = storedRules().getProperty(description);
+
+            if (violations.isEmpty() && existingFileName != null && integrityMode == IntegrityMode.REPAIR) {
+                forgetRule(description, existingFileName);
+                return;
+            }
+            if (violations.isEmpty() && existingFileName == null && integrityMode == IntegrityMode.REPAIR) {
+                return;
+            }
+
+            String fileName = existingFileName != null ? existingFileName : candidateFileName;
+            validateSaveTarget(description, fileName, existingFileName == null);
+            if (existingFileName == null && entryExists(fileName)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Cannot store rule '%s': file name '%s' is already used by the store", description, fileName));
+            }
+
+            boolean targetPreviouslyExisted = entryExists(fileName);
+            try {
+                writeViolations(fileName, violations);
+            } catch (RuntimeException e) {
+                throw e;
+            }
+
+            if (existingFileName == null) {
+                storedRules().put(description, fileName);
+                try {
+                    storedRules().syncFileSystem();
+                } catch (RuntimeException e) {
+                    if (!targetPreviouslyExisted) {
+                        deleteEntryIfPresent(fileName);
+                    }
+                    storedRules().reloadIfPresent();
+                    throw e;
+                }
+            }
+        }
+    }
+
+    private void forgetRule(String description, String fileName) {
+        IntegrityReport report = inspect(storeFolder, storedRulesFile, storedRules(), ruleViolationFileNameStrategy);
+        Entry ownEntry = report.entryFor(description);
+        boolean shared = ownEntry != null && ownEntry.shared;
+        if (!shared) {
+            try {
+                deleteStoredFile(fileName);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules().remove(description);
+        try {
+            storedRules().syncFileSystem();
+        } catch (RuntimeException e) {
+            storedRules().reloadIfPresent();
+            throw e;
+        }
+    }
+
+    private void validateSaveTarget(String description, String fileName, boolean newEntry) {
+        Path target = pathFor(fileName);
+        if (target == null || !isLexicallyDirect(target)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s': file name '%s' does not lead directly into the store folder", description, fileName));
+        }
+        if (sameFile(target, storedRulesFile.toPath())) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s': file name '%s' leads to the index", description, fileName));
+        }
+        if (!newEntry && entryExists(fileName)) {
+            FileResolution resolution = resolve(target);
+            if (!resolution.validDirectRegularFile) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Cannot store rule '%s': file name '%s' does not lead to a regular file directly in the store folder", description, fileName));
+            }
+        }
+    }
+
+    private void writeViolations(String fileName, List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] content = builder.toString().getBytes(UTF_8);
+        Path target = pathFor(fileName);
+        try {
+            if (entryExists(fileName)) {
+                Files.write(target, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+            } else {
+                Path temporary = Files.createTempFile(storeFolder.toPath(), ".violation-", ".tmp");
+                try {
+                    Files.write(temporary, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+                    moveWithoutReplacing(temporary, target);
+                } finally {
+                    Files.deleteIfExists(temporary);
+                }
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        requireInitialized();
+        synchronized (storeState.monitor) {
+            String ruleDetailsFileName = storedRules().getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (isOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(ensureUnixLineBreaks(violationsText))
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private boolean isOnlyLineBreaks(String text) {
+        if (text.isEmpty()) {
+            return true;
+        }
+        for (int i = 0; i < text.length(); i++) {
+            if (text.charAt(i) != '\n' && text.charAt(i) != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return new String(toByteArray(pathFor(fileName).toFile()), UTF_8);
+        } catch (IOException | RuntimeException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private void requireInitialized() {
+        if (storeState == null) {
+            throw new StoreInitializationFailedException("The violation store has not been initialized");
+        }
+    }
+
+    private FileSyncedProperties storedRules() {
+        return storeState.index;
+    }
+
+    private void synchronizedStore(Runnable operation) {
+        requireInitialized();
+        synchronized (storeState.monitor) {
+            operation.run();
+        }
+    }
+
+    private IntegrityReport inspect(File folder, File indexFile, FileSyncedProperties index, RuleViolationFileNameStrategy strategy) {
+        List<Entry> entries = new ArrayList<>();
+        List<String> descriptions = new ArrayList<>(index.keys());
+        Collections.sort(descriptions);
+        for (String description : descriptions) {
+            String name = index.getProperty(description);
+            String derived = requireFileName(strategy.createRuleFileName(description), description);
