+    private void writeViolations(String fileName, List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] content = builder.toString().getBytes(UTF_8);
+        Path target = pathFor(fileName);
+        try {
+            if (entryExists(fileName)) {
+                Files.write(target, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+            } else {
+                Path temporary = Files.createTempFile(storeFolder.toPath(), ".violation-", ".tmp");
+                try {
+                    Files.write(temporary, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+                    moveWithoutReplacing(temporary, target);
+                } finally {
+                    Files.deleteIfExists(temporary);
+                }
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
