+    private IntegrityReport inspect(File folder, File indexFile, FileSyncedProperties index, RuleViolationFileNameStrategy strategy) {
+        List<Entry> entries = new ArrayList<>();
+        List<String> descriptions = new ArrayList<>(index.keys());
+        Collections.sort(descriptions);
+        for (String description : descriptions) {
+            String name = index.getProperty(description);
+            String derived = requireFileName(strategy.createRuleFileName(description), description);
+            Entry entry = new Entry(description, name, derived, pathFor(folder, name), pathFor(folder, derived));
+            entry.resolution = resolve(entry.path, folder, indexFile);
+            entry.broken = !entry.resolution.validDirectRegularFile || entry.resolution.isIndex;
+            if (!entry.broken) {
+                entry.resolved = readLines(entry.resolution.path.toString(), folder).isEmpty();
+            }
+            entries.add(entry);
+        }
+
+        Map<String, Integer> derivedCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            derivedCounts.put(entry.derived, derivedCounts.containsKey(entry.derived) ? derivedCounts.get(entry.derived) + 1 : 1);
+        }
+        for (Entry entry : entries) {
+            entry.misplaced = !Objects.equals(entry.name, entry.derived);
+            entry.colliding = derivedCounts.get(entry.derived) > 1;
+            entry.occupied = entry.misplaced && (!isLexicallyDirect(entry.derivedPath, folder)
+                    || existsAsDirectoryEntry(entry.derivedPath)
+                    || recordsAnotherName(entries, entry.derived, entry));
+        }
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                if (sameNameOrFile(entries.get(i), entries.get(j))) {
+                    entries.get(i).shared = true;
+                    entries.get(j).shared = true;
+                }
+            }
+        }
