+    private List<String> findUnownedFiles(File folder, File indexFile, List<Entry> entries) {
+        List<String> result = new ArrayList<>();
+        Path indexPath = indexFile.toPath().toAbsolutePath().normalize();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(folder.toPath())) {
+            for (Path child : children) {
+                if (!Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                if (child.toAbsolutePath().normalize().equals(indexPath)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (sameFile(entry.path, child)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(child.getFileName().toString());
